// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeSubjectEdition = function (meta, rows) {
  const {subject, year, grade, contest, letters, tasksFile, answersFile, language} = meta;
  const folder = 'assets/' + subject + '/' + year + '/';
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(row => {
    const {title, question, choices, figure, figures, optionFigures, steps, context, audio, numericAnswer} = row;
    const condition = figures?.length ? {items: figures} : figure;
    const options = choices.map((text, i) => {
      const image = optionFigures?.[i];
      if (!image) return {text};
      return {text: row.showOptionText ? text : '', image: image.src,
        description: row.showOptionText ? text + '. ' + image.alt : image.alt,
        ...(image.detailSrc ? {detailSrc: image.detailSrc} : {}),
        pixelWidth: image.width, pixelHeight: image.height};
    });
    return {
      title, question, choices, language, context, guided: true, hideIntroText: true,
      skill: contest, answer: row.answer ?? null,
      points: row.points ?? meta.points,
      ...(row.adaptation ? {questionNote: row.adaptation} : {}),
      ...(row.number ? {number: row.number} : {}),
      ...(Number.isInteger(numericAnswer) ? {numericAnswer} : {}),
      ...(audio ? {audio: folder + (meta.listeningFile ?? 'listening.mp3')} : {}),
      ...(condition || optionFigures ? {choiceLayout: {condition, options},
        choiceImages: options.map(option => option.image),
        ...(condition?.src ? {conditionImage: condition.src, conditionAlt: condition.alt} : {})} : {}),
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ...steps.map((explanation, index) => index === steps.length - 1
          ? ['Проверка', 'Проверка', explanation]
          : [index ? 'Шаг ' + (index + 1) : 'Первый шаг', 'Рассуждение', explanation]),
        ['Ответ', 'Ответ', ''],
      ],
    };
  });
  for (const group of meta.matchingGroups ?? []) {
    const parts = lessons.slice(group.start - 1, group.start - 1 + group.count);
    if (parts.length !== group.count || parts.some(part => !part.conditionImage ||
        JSON.stringify(part.choices) !== JSON.stringify(parts[0].choices))) throw new Error('Incomplete matching group ' + group.title);
    const steps = [
      ['Выбор', 'Условие задачи', ''],
      ...parts.map((part, index) => ['Рисунок ' + (index + 1), part.title,
        part.steps.slice(1, -1).map(step => step[2]).join(' ')]),
      ['Ответ', 'Все пары', ''],
    ];
    for (const part of parts) Object.assign(part, {matching: group, title: group.title, question: group.question, steps});
  }
  return {
    id: [year, subject, meta.session, grade, meta.editionSuffix].filter(Boolean).join('-'), year, grades,
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы') + (meta.sessionTitle ? ' · ' + meta.sessionTitle : '') + (meta.editionLabel ? ' · ' + meta.editionLabel : ''),
    ...(meta.sections ? {sections: meta.sections} : {}),
    ...(meta.titleLanguage ? {titleLanguage: meta.titleLanguage} : {}),
    subject, answerLetters: [...letters], sources: {
      contest, tasksUrl: folder + tasksFile, answersUrl: folder + answersFile,
      ...(meta.reviewedKey ? {reviewedKey: true} : {}),
    },
    lessons, scenes: lessons.map(() => () => ''),
  };
};

register(globalThis.makeSubjectEdition({"subject":"golden-fleece","year":2008,"grade":"5-7","contest":"Золотое руно","letters":"DN?","count":90,"language":"ru","points":3,"tasksFile":"tasks-5-7.pdf","answersFile":"reviewed-5-7.pdf","sections":[{"start":1,"title":"1861–1870"},{"start":19,"title":"1871–1880"},{"start":37,"title":"1881–1890"},{"start":55,"title":"1891–1900"},{"start":73,"title":"1901–1914"}],"reviewedKey":true}, [{"question":"Франко-прусская война завершилась в сентябре 1870 года, сразу после свержения Наполеона III.","context":"1861–1870. События в европе","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Свержение и конец войны","steps":["Наполеон III попал в плен под Седаном в сентябре 1870 года. После этого во Франции провозгласили республику.","Боевые действия продолжились, а Франкфуртский мир подписали в мае 1871 года. Свержение императора не завершило войну."],"reviewedEdition":true},{"question":"Чехия и Словакия отделяются от Австро-Венгрии.","context":"1861–1870. События в европе","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Конец Австро-Венгрии","steps":["Чешские земли и Словакия входили в состав Австро-Венгрии до конца Первой мировой войны.","Чехословакия возникла во время распада империи в 1918 году. Это позже указанного отрезка."]},{"question":"В 1870 году в Версале провозглашается Германская империя.","context":"1861–1870. События в европе","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Провозглашение империи","steps":["В 1870 году Пруссия и южногерманские государства договорились об объединении. Торжественную церемонию провели в Версальском дворце.","Вильгельма I провозгласили германским императором 18 января 1871 года. В условии указан предыдущий год."]},{"question":"В 1863 году Александр II подписывает Манифест об отмене крепостного права.","context":"1861–1870. События в россии","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Дата крестьянской реформы","steps":["Манифест об освобождении крепостных подписал Александр II. По старому стилю дата — 19 февраля 1861 года.","Император назван верно. Год в условии неверен."]},{"question":"Вместе с Аляской Россия продает США Алеутские острова.","context":"1861–1870. События в россии","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Острова при продаже Аляски","steps":["В договоре 1867 года перечислены земли Российской Америки, которые переходили Соединённым Штатам.","В число переданных территорий входили Алеутские острова. Утверждение верно."]},{"question":"В 1865 году остров Сахалин становится полностью российской территорией.","context":"1861–1870. События в россии","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Статус Сахалина","steps":["После договора 1855 года Россия и Япония так и не разделили остров точной границей. Обе стороны продолжали претендовать на Сахалин.","Япония отказалась от прав на Сахалин по договору 1875 года в обмен на Курильские острова. 1865 год не подходит."]},{"question":"Создается Товарищество передвижников.","context":"1861–1870. Новые направления в живописи","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Товарищество художников","steps":["Группа художников организовала выставки, которые можно было перевозить из города в город. Это объясняет прозвище «передвижники».","Товарищество учредили в 1870 году. Первую выставку открыли в следующем году."]},{"question":"Одним из учредителей Товарищества был И. Репин.","context":"1861–1870. Новые направления в живописи","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Репин и передвижники","steps":["Товарищество уже существовало, когда Илья Репин начал показывать свои работы на его выставках.","Полным членом объединения Репин стал позднее, в 1878 году. Среди учредителей его не было."]},{"question":"Ведущими жанрами в искусстве передвижников были бытовая сцена, портрет и пейзаж.","context":"1861–1870. Новые направления в живописи","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Жанры передвижников","steps":["На выставках передвижников показывали повседневную жизнь, портреты современников и природу России. Примеры можно найти у Репина, Крамского и Шишкина.","Бытовая картина, портрет и пейзаж действительно занимали важное место в работе Товарищества."]},{"question":"Этот памятник воздвигнут к тысячелетию России.","context":"1861–1870. Памятники русской истории","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Год открытия памятника","figure":{"src":"assets/golden-fleece/2008/2008_57_II-10.jpg","alt":"На каменном постаменте несколько ярусов фигур, наверху фигуры у державы.","width":307,"height":484},"steps":["На снимке многоярусный памятник с фигурами и державой вверху. Это «Тысячелетие России» в Великом Новгороде.","Памятник открыли в 1862 году. Указанная дата соответствует истории памятника."]},{"question":"Памятник Николаю I в Париже.","context":"1861–1870. Памятники русской истории","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Конный памятник","figure":{"src":"assets/golden-fleece/2008/2008_57_II-11.jpg","alt":"Конная статуя над высоким постаментом с рельефами.","width":307,"height":484},"steps":["У конной статуи многоярусный постамент с рельефами и фигурами. Так выглядит памятник Николаю I на Исаакиевской площади.","На снимке Санкт-Петербург. Император указан верно, Париж — ошибочно."]},{"question":"Памятник Александру I в Хельсинки.","context":"1861–1870. Памятники русской истории","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Памятник у собора","figure":{"src":"assets/golden-fleece/2008/2008_57_II-12.jpg","alt":"Памятник с фигурой наверху и фигурами у основания на фоне светлого собора.","width":307,"height":484},"steps":["На фото памятник на Сенатской площади в Хельсинки. За ним видны стены и купола лютеранского собора.","Памятник посвящён Александру II. В подписи указан другой император."]},{"question":"Название кружку дал А. Рубинштейн.","context":"1861–1870. Появление музыкального объединения «могучая кучка»","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Кто дал название кружку","steps":["В 1867 году критик отозвался о произведениях молодых русских композиторов и употребил выражение «могучая кучка». Позднее оно стало названием кружка.","Критика звали Владимир Стасов. Антон Рубинштейн основал Петербургскую консерваторию, но название кружку дал не он."]},{"question":"Один из членов «Могучей кучки» был выдающимся ученым-химиком.","context":"1861–1870. Появление музыкального объединения «могучая кучка»","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Учёный среди композиторов","steps":["Один из участников кружка занимался органической химией и преподавал в Медико-хирургической академии. Ему же принадлежит музыка оперы «Князь Игорь».","Это Александр Бородин. Он известен и как химик, и как композитор."]},{"question":"Руководителем «Могучей кучки» был М. Глинка.","context":"1861–1870. Появление музыкального объединения «могучая кучка»","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Руководитель композиторов","steps":["Кружок вырос из встреч композиторов вокруг Милия Балакирева. Он обсуждал с товарищами их сочинения и знакомил их с музыкой предшественников.","Михаил Глинка повлиял на их взгляды, но умер в 1857 году и кружком не руководил."]},{"question":"Автор одного из наиболее фундаментальных открытий этого периода – Д. Менделеев.","context":"1861–1870. Научные открытия в области химии и биологии","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Таблица элементов","steps":["Дмитрий Менделеев сравнил свойства известных химических элементов и заметил периодическое повторение этих свойств.","Первый вариант своей таблицы он составил в 1869 году. Этот год входит в заданный период."]},{"question":"А. Нобель изобретает динамит.","context":"1861–1870. Научные открытия в области химии и биологии","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Изобретение Нобеля","steps":["Опасную жидкость нитроглицерин Альфред Нобель соединял с пористым материалом, чтобы получить более устойчивый состав. Изобретение получило название «динамит».","Патент на динамит относится к 1867 году. Указанный отрезок времени подходит."]},{"question":"В России изобретается метод пастеризации пищевых продуктов.","context":"1861–1870. Научные открытия в области химии и биологии","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Где возникла пастеризация","steps":["Метод получил имя Луи Пастера. Во Франции он исследовал, почему вино портится, и предложил недолго нагревать его.","Работа относится к 1860-м годам. Период подходит, а страна в условии указана неверно."]},{"question":"Гражданская война в США.","context":"1871–1880. События в мире","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Война и временной отрезок","steps":["Гражданская война в США продолжалась с 1861 по 1865 год. Она закончилась до начала 1870-х.","Отрезок 1871–1880 годов не подходит. По формату конкурса даже реально существовавшее событие здесь считается неверным."]},{"question":"В 1871 году закон Итальянского королевства перенёс столицу из Флоренции в Рим.","context":"1871–1880. События в мире","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Смена столицы Италии","steps":["Рим вошёл в состав Итальянского королевства в 1870 году. До этого столицей была Флоренция.","Закон о переносе столицы приняли в феврале 1871 года. Поэтому утверждение верно."],"reviewedEdition":true},{"question":"Сан-Стефанский договор 1878 года предусмотрел возможность обменять получаемую Россией Добруджу на Южную Бессарабию.","context":"1871–1880. События в мире","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Мир и Южная Бессарабия","steps":["Предварительный мир после русско-турецкой войны предусматривал передачу Добруджи России и возможность обмена этой территории на Южную Бессарабию.","Такое положение содержалось в статье 19 Сан-Стефанского договора. Окончательную передачу Южной Бессарабии закрепил Берлинский трактат."],"reviewedEdition":true},{"question":"Создание I Интернационала.","context":"1871–1880. Общественно-политические движения в европе","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Первый Интернационал","steps":["Международное товарищество рабочих образовалось на собрании в Лондоне. Организацию также называют Первым Интернационалом.","Создание относится к 1864 году, раньше периода 1871–1880."]},{"question":"Падение Парижской коммуны.","context":"1871–1880. Общественно-политические движения в европе","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Конец Парижской коммуны","steps":["Весной 1871 года в Париже действовала Коммуна. В мае войска правительства взяли город.","Коммуна прекратила существование к концу мая 1871 года. Это начало указанного периода."]},{"question":"Легализация профсоюзов в Англии и Франции.","context":"1871–1880. Общественно-политические движения в европе","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Легализация профсоюзов","steps":["Британский закон признал профсоюзы в 1871 году. Во Франции законодательное разрешение профсоюзов вступило в силу в 1884-м.","Из двух дат отрезку 1871–1880 соответствует только британская. Общее утверждение о двух странах неверно."]},{"question":"Россия вступает в войну с Турцией.","context":"1871–1880. События во внешней политике россии","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Война России с Турцией","steps":["В апреле 1877 года Российская империя объявила войну Османской империи. Итоги войны обсуждались на международных переговорах в 1878 году.","Обе даты входят в период 1871–1880 годов. Утверждение верно."]},{"question":"Отделение от России Бухарского ханства.","context":"1871–1880. События во внешней политике россии","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Статус Бухарского ханства","steps":["После договоров и военных событий второй половины XIX века Бухарский эмират сохранил местного правителя и оказался в зависимости от Российской империи.","Он был её протекторатом. Отделения от России в 1871–1880 годах не было."]},{"question":"Создание «Союза трех императоров».","context":"1871–1880. События во внешней политике россии","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Союз трёх императоров","steps":["Россия, Германия и Австро-Венгрия пытались согласовать внешнеполитические интересы. Руководители трёх монархий сблизились в начале 1870-х.","Договорённость 1873 года известна как Союз трёх императоров. Она входит в указанный отрезок."]},{"question":"Это «Апофеоз войны» Василия Верещагина.","context":"1871–1880. Русская живопись. определите, правильно ли указаны авторы картин","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Автор картины о войне","figure":{"src":"assets/golden-fleece/2008/2008_57_II-28.jpg","alt":"Пирамида из человеческих черепов на земле, вдали горы и птицы.","width":472,"height":295},"steps":["На репродукции пирамида из черепов, над которой кружат птицы. Этот сюжет получил название «Апофеоз войны».","Третьяковская галерея называет автором Василия Верещагина и датирует полотно 1871 годом. Подпись и период верны."],"reviewedEdition":true},{"question":"И. Репин.","context":"1871–1880. Русская живопись. определите, правильно ли указаны авторы картин","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Кто написал косарей","figure":{"src":"assets/golden-fleece/2008/2008_57_II-29.jpg","alt":"Несколько людей косят хлеб на широком поле под светлым небом.","width":508,"height":295},"steps":["На картине крестьяне работают на поле, над ними высокое светлое небо. Полотно называется «Косцы», или «Страдная пора».","Его написал Григорий Мясоедов в 1887 году. Подпись с именем Репина не подходит."]},{"question":"Г. Мясоедов.","context":"1871–1880. Русская живопись. определите, правильно ли указаны авторы картин","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Кто написал бурлаков","figure":{"src":"assets/golden-fleece/2008/2008_57_II-30.jpg","alt":"Люди идут вдоль реки и тянут лямки, вдали видны суда.","width":472,"height":213},"steps":["Вереница людей тянет судно вдоль берега. По сюжету узнаётся картина «Бурлаки на Волге».","Её написал Илья Репин. В условии приведена фамилия Григория Мясоедова."]},{"question":"Дж. Пуччини завершает работу над оперой «Богема».","context":"1871–1880. Оперные постановки, определившие развитие европейского музыкального театра","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Время оперы «Богема»","steps":["Пуччини превратил истории о жизни парижской богемы в оперу. Первую постановку показали в Турине.","Премьера состоялась в 1896 году. Работа над этой оперой относится к 1890-м, а не к указанному периоду."]},{"question":"Грандиозный успех первой постановки оперы Ж. Бизе «Кармен».","context":"1871–1880. Оперные постановки, определившие развитие европейского музыкального театра","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Первая постановка «Кармен»","steps":["Опера Бизе впервые прозвучала в Париже в 1875 году. Новая музыка и необычный для театра сюжет вызвали неоднозначные отзывы.","Большая международная популярность пришла к опере позже. Говорить о грандиозном успехе её первой постановки нельзя."]},{"question":"Премьера тетралогии Р. Вагнера «Кольцо Нибелунга».","context":"1871–1880. Оперные постановки, определившие развитие европейского музыкального театра","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Премьера тетралогии","steps":["«Кольцо Нибелунга» объединяет четыре оперы Вагнера. Некоторые части показали до первого полного исполнения.","Весь цикл впервые представили в Байройте в 1876 году. Это входит в период 1871–1880."]},{"question":"Либретто оперы П. Чайковского «Евгений Онегин», написанной в 1877-1878 годах, полностью следует тексту романа А. Пушкина.","context":"1871–1880. П. чайковский – символ музыкальной россии","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Стихи романа на оперной сцене","steps":["Чайковский использовал пушкинские строки в опере «Евгений Онегин». Но из романа перенесены только некоторые сцены, а текст местами заменён или дополнен.","Опера создана в 1877–1878 годах. Дата верна, утверждение о полном соответствии текста оригиналу неверно."]},{"question":"«Славянский марш», написанный П. Чайковским в 1876 году, посвящен борьбе славянских народов Балкан против Турции.","context":"1871–1880. П. чайковский – символ музыкальной россии","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Повод для «Славянского марша»","steps":["Чайковский написал марш для концерта в пользу нуждающихся участников войны на Балканах. В произведении использованы сербские музыкальные темы.","Этот «Славянский марш» относится к 1876 году и связан с поддержкой славянских народов в борьбе с Османской империей."]},{"question":"В оригинальной партитуре увертюры «1812 год», которую Пётр Чайковский написал в 1880 году, звучат «Марсельеза» и «Боже, Царя храни».","context":"1871–1880. П. чайковский – символ музыкальной россии","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Гимны в увертюре","steps":["Чайковский включил в середину увертюры фрагменты французской «Марсельезы». В финале звучит «Боже, Царя храни».","Обе мелодии присутствуют в оригинальной партитуре 1880 года. Российский гимн был написан в 1833-м и использован композитором как музыкальный символ."],"reviewedEdition":true},{"question":"Введение циркуляра «о кухаркиных детях».","context":"1881–1890. События в россии","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Школьный циркуляр","steps":["Циркуляр министра просвещения ограничивал приём в гимназии детей из небогатых семей. В истории за ним закрепилось название «о кухаркиных детях».","Документ относится к 1887 году. Он появился в указанный период."]},{"question":"После убийства 1 марта 1881 года царя Александра II российский трон переходит к Николаю II .","context":"1881–1890. События в россии","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Преемник Александра II","steps":["Александр II погиб в 1881 году. Престол занял его сын, ставший Александром III.","Николай II, сын Александра III, начал царствовать в 1894 году. В задании пропущено одно правление."]},{"question":"В 1887 году принят закон об ограничении гласности суда.","context":"1881–1890. События в россии","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Гласность суда","steps":["Судебные реформы 1860-х сделали процессы более открытыми для публики. В конце 1880-х возможность проводить закрытые заседания расширили.","Закон, ограничивавший гласность судебных заседаний, относится к 1887 году. Дата в условии соответствует периоду."]},{"question":"В 1885 году греческий крестьянин во время работы на поле обнаруживает в земле статую Венеры Милосской.","context":"1881–1890. АРХЕОЛОГИЧЕСКИЕ открытия","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Находка Венеры Милосской","steps":["Античную статую нашли на греческом острове Милос. Она попала во Францию и хранится в Лувре.","Находка относится к 1820 году. Указанный 1885 год неверен."]},{"question":"Английский археолог Г. Картер открывает гробницу Тутанхамона.","context":"1881–1890. АРХЕОЛОГИЧЕСКИЕ открытия","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Открытие гробницы","steps":["Говард Картер много лет исследовал Долину царей в Египте. Он обнаружил вход в гробницу Тутанхамона после длительных раскопок.","Это произошло в 1922 году. Для периода 1881–1890 событие слишком позднее."]},{"question":"В 1882 году Генрих Шлиман продолжал раскопки Трои на холме Гиссарлык.","context":"1881–1890. АРХЕОЛОГИЧЕСКИЕ открытия","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Раскопки Трои","steps":["Шлиман вёл раскопки на Гиссарлыке несколькими кампаниями. Именно в этом месте археологи выявили слои древней Трои.","Один из сезонов раскопок Шлимана пришёлся на 1882 год. Эта дата входит в указанный период."],"reviewedEdition":true},{"question":"Реализм.","context":"1881–1890. Определите, к каким направлениям живописи относятся эти картины","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Люди в солнечном парке","figure":{"src":"assets/golden-fleece/2008/2008_57_II-43.jpg","alt":"Люди стоят и сидят у реки, некоторые держат зонтики, всё пространство в цветных мазках.","width":472,"height":331},"steps":["В композиции изображены отдыхающие на острове Гранд-Жатт. Картина Жоржа Сёра собрана из множества мелких цветовых мазков.","Этот подход называют пуантилизмом или относят к неоимпрессионизму. Подпись «реализм» не передаёт направления картины."]},{"question":"Сюрреализм.","context":"1881–1890. Определите, к каким направлениям живописи относятся эти картины","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Небо с вихрями","figure":{"src":"assets/golden-fleece/2008/2008_57_II-44.jpg","alt":"Звёздное небо с вихрями, тёмный кипарис и небольшой посёлок.","width":449,"height":354},"steps":["На картине яркие звёзды и длинные вихри над ночным посёлком. Это «Звёздная ночь» Винсента ван Гога, созданная в 1889 году.","Ван Гога относят к постимпрессионизму. Сюрреализм сформировался десятилетиями позже."]},{"question":"Импрессионизм.","context":"1881–1890. Определите, к каким направлениям живописи относятся эти картины","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Мазки городского пейзажа","figure":{"src":"assets/golden-fleece/2008/2008_57_II-45.jpg","alt":"Светлые дома у воды и их отражения переданы отдельными цветными мазками.","width":472,"height":272},"steps":["Художник передал вид воды и домов лёгкими цветными мазками. Внимание сосредоточено на свете и отражениях.","Такая манера характерна для импрессионизма. В задании направление названо верно."]},{"question":"Р. Вагнер пишет последнюю оперу «Парсифаль».","context":"1881–1890. Музыкальная жизнь","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Последняя опера Вагнера","steps":["«Парсифаль» рассказывает о рыцарях Святого Грааля. Вагнер закончил партитуру и впервые представил произведение в Байройте в 1882 году.","Это последнее его завершённое произведение для музыкальной сцены. Период 1881–1890 подходит."]},{"question":"Дж. Верди пишет оперу «Аида» к торжественному открытию Суэцкого канала.","context":"1881–1890. Музыкальная жизнь","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Опера и открытие канала","steps":["Суэцкий канал открыли в 1869 году. Опера об эфиопской царевне была заказана для Каира и впервые прозвучала там в 1871-м.","Верди написал «Аиду», но премьера состоялась после открытия канала. Оба события произошли раньше периода 1881–1890."]},{"question":"В 1888 году Н. Римский-Корсаков, находясь под впечатлением от арабских сказок «Тысяча и одна ночь», пишет симфоническую сюиту «Шехеразада».","context":"1881–1890. Музыкальная жизнь","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Сказки в симфонии","steps":["В оркестровой сюите звучат темы, навеянные историями из «Тысячи и одной ночи». Название напоминает о рассказчице Шехеразаде.","Сюиту «Шехеразада» Римский-Корсаков написал в 1888 году. Атрибуция и дата верны."]},{"question":"В 1886 году А. Белл изобретает телефон.","context":"1881–1890. Технические изобретения","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Белл и дата телефона","steps":["Александр Грэм Белл получил патент на телефон и испытывал его в 1876 году. Уже тогда удалось передать по проводу разборчивую речь.","В задаче приведён 1886 год. Он на десять лет позже указанного события."]},{"question":"Г. Даймлер патентует изобретение мотоцикла – «повозки для верховой езды с керосиновым двигателем».","context":"1881–1890. Технические изобретения","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Ранняя моторная повозка","steps":["В 1885 году Готлиб Даймлер и Вильгельм Майбах испытали двухколёсную повозку с небольшим двигателем внутреннего сгорания.","Её называли Reitwagen, то есть повозкой для верховой езды. Патент и испытания относятся к заданному десятилетию."]},{"question":"Т. Эдисон в 1887 году изобретает лампу накаливания.","context":"1881–1890. Технические изобретения","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Лампа накаливания","steps":["Эдисон и его сотрудники испытали долговечную лампу с угольной нитью в 1879 году. Патент был выдан в 1880-м.","Обе даты раньше 1887 года. Над лампами накаливания тогда работали и другие изобретатели."]},{"question":"В 1882 году Роберт Кох представил результаты исследования возбудителя туберкулёза, микобактерии туберкулёза.","context":"1881–1890. Научные открытия","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Возбудитель туберкулёза","steps":["Кох изучил бактерии, обнаруженные у больных туберкулёзом. Он связал конкретную микобактерию с развитием болезни.","Учёный сообщил о своём открытии в 1882 году. Утверждение верно."],"reviewedEdition":true},{"question":"В 1887 году В. Рентген устанавливает волновую природу электричества.","context":"1881–1890. Научные открытия","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Опыты с волнами","steps":["В конце 1880-х электромагнитные волны экспериментально изучал Генрих Герц. Работы подтвердили предсказания электромагнитной теории.","Вильгельм Рентген в 1895 году открыл другой вид лучей. Имя и описание в задании перепутаны."]},{"question":"В 1883 году Р. Дизель изобретает двигатель внутреннего сгорания.","context":"1881–1890. Научные открытия","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Двигатель Дизеля","steps":["Принцип двигателей с внутренним сгоранием был известен до работ Рудольфа Дизеля. Он разработал собственный способ воспламенять топливо за счёт сжатия.","Дизель запатентовал свой принцип в 1890-х, а работоспособный двигатель испытали в 1897 году. Дата 1883 неверна."]},{"question":"В 1898 году на Аляске около Нома нашли золото.","context":"1891–1900. События в мире","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Золотая лихорадка","steps":["Ном находится на западном побережье Аляски. Рядом с ним золото обнаружили в 1898 году, и вскоре туда приехали старатели.","Событие произошло в указанный период. Отдельная золотая лихорадка в Клондайке началась в 1896 году на территории канадского Юкона."],"reviewedEdition":true},{"question":"Историю Новосибирска отсчитывают от появления в 1893 году поселения строителей железнодорожного моста через Обь.","context":"1891–1900. События в мире","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Основание Новониколаевска","steps":["В 1893 году рядом со стройкой моста через Обь появилось постоянное поселение. Из него вырос Ново-Николаевск, современный Новосибирск.","1893 год считается началом истории поселения. Статус города Ново-Николаевск получил позднее, в 1903 году по старому стилю."],"reviewedEdition":true},{"question":"Завершается строительство Панамского канала.","context":"1891–1900. События в мире","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Даты Панамского канала","steps":["Французская компания начала работы на Панамском перешейке в 1881 году. После перерыва строительство продолжили под руководством США.","Канал официально открыли в 1914 году. В 1891–1900 годах работы не завершились."]},{"question":"В. Ленин создает «Союз борьбы за освобождение рабочего класса».","context":"1891–1900. Общественные движения","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Союз рабочих кружков","steps":["В 1895 году петербургские марксистские кружки объединились в «Союз борьбы за освобождение рабочего класса».","В объединении участвовали Владимир Ленин и Юлий Мартов. Указанное событие входит в заданный период."]},{"question":"В Париже основан Международный олимпийский комитет.","context":"1891–1900. Общественные движения","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Год создания МОК","steps":["В 1894 году в Париже прошёл конгресс по возрождению Олимпийских игр. По его результатам создали Международный олимпийский комитет.","1894 год подходит. Первые современные Игры открылись в Афинах двумя годами позже."]},{"question":"К. Маркс начинает писать «Капитал».","context":"1891–1900. Общественные движения","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Когда появился «Капитал»","steps":["Карл Маркс много лет писал труд о капиталистической экономике. Первый том «Капитала» вышел в 1867 году.","К 1891 году Маркс уже умер. В указанный период выходили подготовленные другими тома, но начать книгу тогда он не мог."]},{"question":"Открытие Русского музея в Санкт-Петербурге.","context":"1891–1900. Художественные объединения и музеи","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Открытие Русского музея","steps":["Русский музей создавали как собрание произведений отечественного искусства. Для него отвели Михайловский дворец в Санкт-Петербурге.","Музей торжественно открыли в 1898 году. Город и период указаны верно."]},{"question":"Открытие в Москве Музея изящных искусств имени Александра III.","context":"1891–1900. Художественные объединения и музеи","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Московский музей искусства","steps":["Музей имени императора Александра III строили как общедоступное собрание по истории искусства. Сейчас это ГМИИ имени Пушкина.","Музей открылся в Москве в 1912 году. Отрезок 1891–1900 для открытия не подходит."]},{"question":"В 1893 году в Москве для посетителей открылась городская галерея Павла и Сергея Третьяковых.","context":"1891–1900. Художественные объединения и музеи","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Даты Третьяковской галереи","steps":["Павел Третьяков передал свои картины и собрание брата городу в 1892 году. После передачи оформили городскую галерею.","Московская городская галерея Павла и Сергея Третьяковых открылась для посетителей в 1893 году."],"reviewedEdition":true},{"question":"На фрагменте показано полотно Ильи Репина.","context":"1891–1900. Исторические полотна. определите, правильно ли поставлены авторы фрагментов картин","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Автор полотна о Ермаке","steps":["У речного берега видны лодки и участники исторического сражения. Это эпизод похода Ермака.","«Покорение Сибири Ермаком» написал Василий Суриков. Русский музей датирует полотно 1895 годом."],"figure":{"src":"assets/golden-fleece/2008/2008_24_I-61.jpg","alt":"Много людей в лодках у высокого речного берега, над водой клубы дыма.","width":461,"height":272},"adaptation":"Репродукция для учебного задания подобрана редакцией Olympiads.pro.","reviewedEdition":true},{"question":"На фрагменте показано полотно Виктора Васнецова.","context":"1891–1900. Исторические полотна. определите, правильно ли поставлены авторы фрагментов картин","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Автор полотна о казаках","steps":["Люди в казачьей одежде окружили писаря. Они с удовольствием подсказывают ему слова письма.","Это «Запорожцы» Ильи Репина. Во фрагменте показана его картина, а подпись указывает другого художника."],"figure":{"src":"assets/golden-fleece/2008/2008_24_I-62.jpg","alt":"Толпа людей в казачьей одежде окружает писаря у стола.","width":461,"height":272},"adaptation":"Репродукция для учебного задания подобрана редакцией Olympiads.pro.","reviewedEdition":true},{"question":"На фрагменте показано полотно Василия Сурикова.","context":"1891–1900. Исторические полотна. определите, правильно ли поставлены авторы фрагментов картин","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Автор полотна об Альпах","steps":["Солдаты спускаются по крутому снежному склону. Историческое событие, которое изобразил художник, — переход армии Суворова через Альпы.","«Переход Суворова через Альпы» написал Василий Суриков в 1899 году. Подпись верна."],"figure":{"src":"assets/golden-fleece/2008/2008_24_I-63.jpg","alt":"Военные спускаются по крутому снежному склону в горах.","width":449,"height":272},"adaptation":"Репродукция для учебного задания подобрана редакцией Olympiads.pro.","reviewedEdition":true},{"question":"Торжественное открытие Государственной оперы в Вене.","context":"1891–1900. Новые оперные сцены мира","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Открытие Венской оперы","steps":["Здание Венской оперы на кольцевой улице открылось постановкой «Дон Жуана» Моцарта.","Это произошло в 1869 году. Торжество не входит в период 1891–1900."]},{"question":"Завершение строительства театра «Колон» в Аргентине – одного из самых больших театров мира.","context":"1891–1900. Новые оперные сцены мира","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Театр Буэнос-Айреса","steps":["Нынешнее здание театра «Колон» в Буэнос-Айресе строили много лет. Работы начались в конце XIX века.","Новый театр открыли в 1908 году постановкой «Аиды». В 1891–1900 годах строительство ещё продолжалось."]},{"question":"Строительство «Гранд-Опера» в Париже.","context":"1891–1900. Новые оперные сцены мира","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Стройка Оперы Гарнье","steps":["Театр в Париже строили по проекту Шарля Гарнье, выбранному в начале 1860-х годов. Здание открылось для публики в 1875-м.","В конце XIX века опера уже работала в этом здании. Период 1891–1900 для стройки не подходит."]},{"question":"А. Скрябин сочиняет первую симфонию.","context":"1891–1900. Новые имена в русской музыке","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Первая симфония Скрябина","steps":["В первой симфонии Скрябина шесть частей. В её финале хор и солисты поют о силе искусства.","Скрябин работал над произведением на рубеже веков и завершил его в 1900 году. Дата входит в указанный период."]},{"question":"А. Рубинштейн проводит первый международный конкурс музыкантов-исполнителей.","context":"1891–1900. Новые имена в русской музыке","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Музыкальный конкурс","steps":["Антон Рубинштейн учредил международный конкурс, на котором состязались пианисты и композиторы. Первые состязания прошли в Петербурге.","Это случилось в 1890 году. Первый год заданного отрезка — 1891-й."]},{"question":"Сергей Рахманинов закончил первоначальную редакцию Первого концерта для фортепиано с оркестром в 1891 году.","context":"1891–1900. Новые имена в русской музыке","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Первый концерт Рахманинова","steps":["Рахманинов начал делать наброски концерта в 1890 году. В 1891 году он довёл работу над первоначальной редакцией до конца.","Речь о завершении первой редакции, поэтому 1891 год верен. В 1917 году композитор вернулся к концерту и переработал его."],"reviewedEdition":true},{"question":"Первая Балканская война.","context":"1901–1914. События в мире","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Первая Балканская война","steps":["Война Балканского союза с Османской империей началась в октябре 1912 года. Мир заключили в 1913-м.","Обе даты входят в период 1901–1914. Утверждение верно."]},{"question":"Англо-русское соглашение 1907 года завершило формирование Тройственной Антанты.","context":"1901–1914. События в мире","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Когда возникла Антанта","steps":["В 1904 году Великобритания и Франция заключили соглашение и решили часть спорных вопросов. Третьим участником сближения стала Россия.","Великобритания и Россия договорились в 1907 году. Это соглашение считается последним шагом в формировании Тройственной Антанты."],"reviewedEdition":true},{"question":"Благодаря победе в Цусимском сражении Россия побеждает в русско-японской войне.","context":"1901–1914. События в мире","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Цусима и итог войны","steps":["В мае 1905 года у Цусимы победил японский флот. Русская эскадра потеряла большую часть кораблей.","По Портсмутскому миру Япония получила несколько уступок. И сражение, и общий итог в формулировке указаны неверно."]},{"question":"Толчком к революции стал расстрел демонстрации в Санкт-Петербурге 9 января 1905 года.","context":"1901–1914. 1905 год – кровавый год русской истории","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Январская демонстрация","steps":["В Петербурге рабочие шли с петицией к императору. Войска открыли огонь по демонстрантам. Это событие известно как Кровавое воскресенье.","По действовавшему тогда в России календарю это произошло 9 января 1905 года. Событие стало одним из толчков к революции."]},{"question":"Броненосец «Потемкин» входит в устье Невы.","context":"1901–1914. 1905 год – кровавый год русской истории","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Маршрут «Потёмкина»","steps":["Восстание на броненосце произошло в Чёрном море. Корабль заходил к Одессе, а позднее пришёл в румынскую Констанцу.","Нева относится к бассейну Балтийского моря. В устье Невы «Потёмкин» в ходе этих событий не входил."]},{"question":"8 июля 1905 года распущена Государственная дума.","context":"1901–1914. 1905 год – кровавый год русской истории","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Роспуск Думы","steps":["Первую Государственную думу созвали весной 1906 года. Она проработала всего несколько месяцев.","8 июля по старому стилю её распустили, но это произошло в 1906 году. В задаче указан 1905-й."]},{"question":"В 1907 году в Париже Сергей Дягилев организовал серию «Исторические русские концерты».","context":"1901–1914. События в жизни театра","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Начало «Русских сезонов»","steps":["Парижской публике представили произведения русских композиторов. Среди участников был оперный певец Фёдор Шаляпин.","Эти концерты прошли в 1907 году. Балетные спектакли Дягилев впервые включил в парижскую программу в 1909 году."],"reviewedEdition":true},{"question":"Организатор «Русских сезонов» – С. Дягилев.","context":"1901–1914. События в жизни театра","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Кто устроил «Русские сезоны»","steps":["Для парижских выступлений организатор собрал композиторов, художников и танцовщиков. Благодаря гастролям многие из них стали известны за пределами России.","Предприятием руководил Сергей Дягилев. Утверждение о нём верно."]},{"question":"В 1910 году в Париже состоялись премьеры балетов И. Стравинского «Петрушка» и «Весна священная».","context":"1901–1914. События в жизни театра","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Даты балетных премьер","steps":["«Петрушка» впервые прозвучал на парижской сцене в 1911 году, а «Весна священная» — в 1913-м.","В 1910 году в Париже показали другой балет Стравинского, «Жар-птицу». Ни одна из двух названных премьер не относится к 1910 году."]},{"question":"Нобелевские премии присуждаются начиная с 1901 года.","context":"1901–1914. Нобелевские премии","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Первые Нобелевские премии","steps":["Альфред Нобель предусмотрел в завещании ежегодные награды за достижения в науке, литературе и деле мира.","Первые Нобелевские премии вручили в 1901 году. Эта дата верна."]},{"question":"Химический элемент нобелий получил имя Альфреда Нобеля в 1901–1914 годах.","context":"1901–1914. Нобелевские премии","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Химический элемент","steps":["Элемент с атомным номером 102 назвали в честь Альфреда Нобеля. Его исследовали в середине XX века.","Название появилось в научной литературе в 1950-х годах. Оно относится к более позднему времени."],"reviewedEdition":true},{"question":"И. Бунин – первый российский лауреат Нобелевской премии.","context":"1901–1914. Нобелевские премии","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Первый лауреат из России","steps":["Иван Павлов получил Нобелевскую премию по физиологии или медицине в 1904 году. Ивану Бунину премию по литературе присудили в 1933-м.","Бунин стал первым русским лауреатом именно литературной премии. Первым российским нобелевским лауреатом вообще был Павлов."]},{"question":"Антон Чехов закончил первый полный черновик пьесы «Три сестры» в 1900 году.","context":"1901–1914. Русская литература","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Работа над «Тремя сёстрами»","steps":["Чехов начал работу над пьесой летом 1900 года. Полный черновик он закончил в Ялте в октябре того же года.","Правки и подготовка спектакля продолжились позже. Московский Художественный театр впервые показал пьесу в январе 1901 года."],"reviewedEdition":true},{"question":"«Драматическую симфонию» и «Северную симфонию» Андрея Белого впервые издали в 1902–1904 годах.","context":"1901–1914. Русская литература","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Симфонии Андрея Белого","steps":["«Драматическая симфония» вышла в 1902 году. «Северную симфонию», которую также называют «героической», издали в 1904-м.","Обе даты первых изданий входят в указанный отрезок. Над «Северной симфонией» Белый начал работать раньше."],"reviewedEdition":true},{"question":"В 1906 году Л. Толстой пишет свой последний роман «Воскресение».","context":"1901–1914. Русская литература","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Последний роман Толстого","steps":["Толстой работал над романом «Воскресение» в 1890-е годы. Опубликован он был в 1899-м.","Дата 1906 не соответствует времени работы над последним романом."]},{"question":"Венгерская палата депутатов впервые провела заседание в показанном на фотографии здании в 1902 году.","context":"Символы городов мира. Проверьте дату.","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Здание у Дуная","figure":{"src":"assets/golden-fleece/2008/2008_57_II-88.jpg","alt":"Длинное здание со шпилями и большим центральным куполом на берегу реки.","width":295,"height":425},"steps":["Неоготический фасад со шпилями и большой центральный купол видны с Дуная. Это здание венгерского парламента в Будапеште.","Библиотека парламента указывает дату первого заседания палаты депутатов в здании — 8 октября 1902 года."],"reviewedEdition":true},{"question":"1906 год.","context":"1901–1914. Символы городов мира. определите, верно ли указаны годы их создания","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Фигура с факелом","figure":{"src":"assets/golden-fleece/2008/2008_57_II-89.jpg","alt":"Высокая фигура с факелом и короной на каменном постаменте.","width":307,"height":425},"steps":["На снимке Статуя Свободы, установленная на острове в гавани Нью-Йорка.","Памятник открыли в 1886 году. Дата 1906 в подписи неверна."]},{"question":"1912 год.","context":"1901–1914. Символы городов мира. определите, верно ли указаны годы их создания","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Статуя над городом","figure":{"src":"assets/golden-fleece/2008/2008_24_I-90.jpg","alt":"Высокая статуя с распростёртыми руками на фоне неба.","width":343,"height":425},"steps":["Фигура с распростёртыми руками — статуя Христа-Искупителя на горе Корковаду в Рио-де-Жанейро.","Памятник открыли в 1931 году. В 1912-м статуя ещё не была создана."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
